hand(3):
  - die=d-0002 def=die_strike school=neutral risk=safe face=5 kind=purge value=7 label=蓄力斩 7 corrupt=no
  - die=d-0008 def=die_utility school=neutral risk=safe face=5 kind=purge value=4 label=刺击 4 corrupt=no
  - die=d-0005 def=die_mend school=neutral risk=safe face=4 kind=mend value=5 label=修复 5 corrupt=no
slots(5):
  - slot=slot_1 kind=attack constraint=any effect=purge bonus=0 disabled=no
  - slot=slot_2 kind=attack constraint=ge:3 effect=purge bonus=1 disabled=no
  - slot=slot_3 kind=defense constraint=any effect=ward bonus=0 disabled=no
  - slot=slot_4 kind=heal constraint=even effect=mend bonus=1 disabled=no
  - slot=slot_5 kind=utility constraint=any effect=any bonus=0 disabled=no
enemies(1):
  - enemy=e-00 def=mon_verdant_slime school=verdant hp=7/7 ward=0 phase=1 taunt=自然 · 黏滑的腐殖体 status=- intent=kind=purge value=1 school=verdant arrow=eq slot=e_slot_0;kind=ward value=3 school=verdant arrow=eq slot=e_slot_1
